PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX pizza: <http://www.co-ode.org/ontologies/pizza/pizza.owl#>

SELECT ?pizza WHERE {
  ?pizza owl:equivalentClass [
    owl:intersectionOf (
      pizza:Pizza
      [ owl:onProperty pizza:hasTopping ;
        owl:allValuesFrom [
          owl:intersectionOf (
            pizza:SpicyTopping
          )
        ]
      ]
    )
  ] .
}

